#!/usr/bin/env python3
"""Inspect, underline, and verify headlines in quarterly_report.docx.

Modes:
  inspect  - unpack the docx and report heading styles / paragraphs (no changes)
  edit     - underline all headline runs, pack the docx back, and verify
  verify   - re-open the packed docx and confirm every headline run is underlined
"""

import random
import shutil
import sys
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent
SKILL_ROOT = ROOT / ".codex/skills/docx"
VENDOR = ROOT / "vendor"
sys.path.insert(0, str(VENDOR))
sys.path.insert(0, str(SKILL_ROOT))

from defusedxml import minidom  # noqa: E402  (stdlib-backed shim)

DOCX = ROOT / "quarterly_report.docx"
UNPACKED = ROOT / "unpacked"
BACKUP = ROOT / "quarterly_report.backup.docx"

# CT_RPr child order (subset relevant for placement of w:u)
RPR_ORDER = [
    "w:rStyle", "w:rFonts", "w:b", "w:bCs", "w:i", "w:iCs", "w:caps",
    "w:smallCaps", "w:strike", "w:dstrike", "w:outline", "w:shadow",
    "w:emboss", "w:imprint", "w:noProof", "w:snapToGrid", "w:vanish",
    "w:webHidden", "w:color", "w:spacing", "w:w", "w:kern", "w:position",
    "w:sz", "w:szCs", "w:highlight", "w:u", "w:effect", "w:bdr", "w:shd",
    "w:fitText", "w:vertAlign", "w:rtl", "w:cs", "w:em", "w:lang",
    "w:eastAsianLayout", "w:specVanish", "w:oMath",
]
U_INDEX = RPR_ORDER.index("w:u")


def unpack(docx_path, out_dir):
    out = Path(out_dir)
    if out.exists():
        shutil.rmtree(out)
    out.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(docx_path) as zf:
        zf.extractall(out)
    for xml_file in list(out.rglob("*.xml")) + list(out.rglob("*.rels")):
        content = xml_file.read_text(encoding="utf-8")
        dom = minidom.parseString(content)
        xml_file.write_bytes(dom.toprettyxml(indent="  ", encoding="ascii"))
    return out


def heading_style(para):
    """Return the style id if para is a headline paragraph, else None."""
    for child in para.childNodes:
        if child.nodeType != child.ELEMENT_NODE or child.tagName != "w:pPr":
            continue
        for ppr_child in child.childNodes:
            if (
                ppr_child.nodeType != ppr_child.ELEMENT_NODE
                or ppr_child.tagName != "w:pStyle"
            ):
                continue
            val = ppr_child.getAttribute("w:val")
            if val == "Title" or val.startswith("Heading"):
                return val
        break
    return None


def para_text(para):
    parts = []
    for node in para.getElementsByTagName("w:t"):
        if node.firstChild and node.firstChild.nodeType == node.firstChild.TEXT_NODE:
            parts.append(node.firstChild.data)
    return "".join(parts)


def run_has_underline(run):
    for child in run.childNodes:
        if child.nodeType != child.ELEMENT_NODE or child.tagName != "w:rPr":
            continue
        for cc in child.childNodes:
            if cc.nodeType == cc.ELEMENT_NODE and cc.tagName == "w:u":
                return True
    return False


def ensure_underline(dom, run):
    """Add <w:u w:val='single'/> to the run's rPr (schema-order aware)."""
    rPr = None
    for child in run.childNodes:
        if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:rPr":
            rPr = child
            break
    if rPr is None:
        rPr = dom.createElement("w:rPr")
        run.insertBefore(rPr, run.firstChild)
    if run_has_underline(run):
        return False
    u = dom.createElement("w:u")
    u.setAttribute("w:val", "single")
    before = None
    for child in rPr.childNodes:
        if child.nodeType != child.ELEMENT_NODE:
            continue
        idx = RPR_ORDER.index(child.tagName) if child.tagName in RPR_ORDER else len(RPR_ORDER)
        if idx > U_INDEX:
            before = child
            break
    if before is not None:
        rPr.insertBefore(u, before)
    else:
        rPr.appendChild(u)
    return True


def collect_headings(dom):
    headings = []
    for p in dom.getElementsByTagName("w:p"):
        st = heading_style(p)
        if st:
            headings.append((st, p))
    return headings


def inspect():
    if not DOCX.exists():
        print(f"ERROR: {DOCX} not found")
        sys.exit(1)
    unpacked = unpack(DOCX, UNPACKED)

    from scripts.utilities import XMLEditor  # noqa: E402

    editor = XMLEditor(unpacked / "word/document.xml")
    dom = editor.dom

    style_counts = {}
    for p in dom.getElementsByTagName("w:p"):
        for child in p.childNodes:
            if child.nodeType != child.ELEMENT_NODE or child.tagName != "w:pPr":
                continue
            for ppr_child in child.childNodes:
                if (
                    ppr_child.nodeType != ppr_child.ELEMENT_NODE
                    or ppr_child.tagName != "w:pStyle"
                ):
                    continue
                val = ppr_child.getAttribute("w:val")
                style_counts[val] = style_counts.get(val, 0) + 1
            break

    print("Distinct paragraph styles in document.xml:")
    for val, cnt in sorted(style_counts.items()):
        print(f"  {val}: {cnt}")

    headings = collect_headings(dom)
    print(f"\nHeadline paragraphs ({len(headings)}):")
    for st, p in headings:
        print(f"  [{st}] {para_text(p)!r}")

    print(
        f"\nTracked changes present: "
        f"{len(dom.getElementsByTagName('w:ins'))} ins, "
        f"{len(dom.getElementsByTagName('w:del'))} del"
    )
    rsid = "".join(random.choices("0123456789ABCDEF", k=8))
    print(f"Suggested RSID for edit session: {rsid}")


def edit():
    if not DOCX.exists():
        print(f"ERROR: {DOCX} not found")
        sys.exit(1)
    unpacked = unpack(DOCX, UNPACKED)

    from scripts.utilities import XMLEditor  # noqa: E402
    from ooxml.scripts.pack import pack_document  # noqa: E402

    editor = XMLEditor(unpacked / "word/document.xml")
    dom = editor.dom

    headings = collect_headings(dom)
    if not headings:
        print("ERROR: no headline paragraphs (Title/Heading*) found; nothing to do")
        sys.exit(1)

    total_runs = 0
    report = []
    for st, p in headings:
        runs = p.getElementsByTagName("w:r")
        n = sum(1 for r in runs if ensure_underline(dom, r))
        total_runs += n
        report.append((st, para_text(p), len(runs), n))

    editor.save()

    for st, text, total, n in report:
        print(f"  [{st}] {text!r}: {n}/{total} runs underlined")
    print(f"Total runs newly underlined: {total_runs}")

    if not BACKUP.exists():
        shutil.copy2(DOCX, BACKUP)
        print(f"Local backup created: {BACKUP.name}")

    ok = pack_document(unpacked, DOCX, validate=False)
    print(f"Pack result: {'success' if ok else 'FAILED'}")
    if not ok:
        sys.exit(1)

    if verify(DOCX):
        print("EDIT + VERIFY OK")
    else:
        sys.exit(1)


def verify(docx_path):
    with zipfile.ZipFile(docx_path) as zf:
        xml_bytes = zf.read("word/document.xml")
    dom = minidom.parseString(xml_bytes.decode("utf-8"))

    headings = collect_headings(dom)
    problems = []
    for st, p in headings:
        for r in p.getElementsByTagName("w:r"):
            if not run_has_underline(r):
                problems.append((st, para_text(p)))
    print(f"\nVerification: {len(headings)} headline paragraphs checked")
    if problems:
        print("PROBLEMS (runs without underline):")
        for st, text in problems:
            print(f"  [{st}] {text!r}")
        return False
    print("All runs in all headline paragraphs are underlined.")
    return True


if __name__ == "__main__":
    mode = sys.argv[1] if len(sys.argv) > 1 else "inspect"
    if mode == "inspect":
        inspect()
    elif mode == "edit":
        edit()
    elif mode == "verify":
        if not DOCX.exists():
            print(f"ERROR: {DOCX} not found")
            sys.exit(1)
        sys.exit(0 if verify(DOCX) else 1)
    else:
        print(f"Unknown mode: {mode}")
        sys.exit(2)

