import os, shutil
try:
    from defusedxml import minidom
except ImportError:
    from xml.dom import minidom

# Back up original document before any modification
if not os.path.exists('quarterly_report.backup.docx'):
    shutil.copy2('quarterly_report.docx', 'quarterly_report.backup.docx')

path = 'unpacked/word/document.xml'
dom = minidom.parse(path)
body = dom.getElementsByTagName('w:body')[0]
paras = body.getElementsByTagName('w:p')

def para_text(p):
    parts = []
    for t in p.getElementsByTagName('w:t'):
        parts.append(t.firstChild.nodeValue if t.firstChild else '')
    return ''.join(parts)

def is_headline(text):
    return bool(text) and any(c.isalpha() for c in text) and text == text.upper() and not text.startswith('\u2022')

def make_underline_elem(doc):
    u = doc.createElement('w:u')
    u.setAttribute('w:val', 'single')
    return u

def insert_with_indent(parent, elem, indent_text):
    """Insert elem into parent before trailing whitespace, keeping pretty layout."""
    # find trailing whitespace-only text node
    trailing = None
    for ch in parent.childNodes:
        if ch.nodeType == 3 and ch.data.isspace() and ch is parent.lastChild:
            trailing = ch
    if trailing is not None:
        parent.insertBefore(elem, trailing)
        parent.insertBefore(parent.ownerDocument.createTextNode(indent_text), elem)
    else:
        parent.appendChild(elem)

headlines = []
for p in paras:
    text = para_text(p)
    if is_headline(text):
        headlines.append(text)
        # underline each run
        for r in p.getElementsByTagName('w:r'):
            rprs = r.getElementsByTagName('w:rPr')
            if rprs:
                rpr = rprs[0]
                if not rpr.getElementsByTagName('w:u'):
                    insert_with_indent(rpr, make_underline_elem(dom), '\n          ')
            else:
                rpr = dom.createElement('w:rPr')
                rpr.appendChild(make_underline_elem(dom))
                r.insertBefore(rpr, r.firstChild)
        # underline paragraph mark
        pprs = p.getElementsByTagName('w:pPr')
        if pprs:
            ppr = pprs[0]
            if not ppr.getElementsByTagName('w:rPr'):
                rpr = dom.createElement('w:rPr')
                u = make_underline_elem(dom)
                rpr.appendChild(dom.createTextNode('\n          '))
                rpr.appendChild(u)
                rpr.appendChild(dom.createTextNode('\n        '))
                ppr.appendChild(dom.createTextNode('\n        '))
                ppr.appendChild(rpr)
                ppr.appendChild(dom.createTextNode('\n      '))

print('headlines found:', len(headlines))
for h in headlines:
    print(' -', h)

with open(path, 'w', encoding='ascii', newline='\n') as f:
    dom.writexml(f, encoding='ascii')
print('written', path)

