    print(f"\nVerification: {len(headings)} headline paragraphs checked")
    if problems:
        print("PROBLEMS (runs without underline):")
        for st, text in problems:
            print(f"  [{st}] {text!r}")
        return False
    print("All runs in all headline paragraphs are underlined.")
    return True


if __name__ == "__main__":
    mode = sys.argv[1] if len(sys.argv) > 1 else "inspect"
    if mode == "inspect":
        inspect()
    elif mode == "edit":
        edit()
    elif mode == "verify":
        if not DOCX.exists():
            print(f"ERROR: {DOCX} not found")
            sys.exit(1)
        sys.exit(0 if verify(DOCX) else 1)
    else:
        print(f"Unknown mode: {mode}")
        sys.exit(2)

